import {
  FDO_SDK,
  FDOInterface,
  PluginMetadata,
  PluginRegistry,
} from "@anikitenko/fdo-sdk";
import { render } from "./render";
import { actionBindings } from "./actions";

class WebToolsWorkbenchPlugin extends FDO_SDK implements FDOInterface {
  private readonly _metadata: PluginMetadata = {
    name: "Web Tools Workbench",
    version: "1.0.0",
    author: "FDO Plugin Workspace",
    description: "Local deterministic webmaster utilities dashboard.",
    icon: "applications",
  };

  get metadata(): PluginMetadata {
    return this._metadata;
  }

  init(): void {
    this.info("Web Tools Workbench initialized");
    PluginRegistry.registerHandler(
      "webToolsWorkbench.render",
      () => render()
    );
  }

  render(): string {
    return render();
  }

  renderOnLoad(): string {
    return actionBindings;
  }
}

export default WebToolsWorkbenchPlugin;
