export type TextCaseMode = "upper" | "lower" | "title";

export interface TextTransformResult {
  ok: boolean;
  value?: string;
  chars?: number;
  words?: number;
  error?: string;
}

function isTextMode(mode: string): mode is TextCaseMode {
  return mode === "upper" || mode === "lower" || mode === "title";
}

function normalizeCase(value: string, mode: TextCaseMode): string {
  if (mode === "upper") {
    return value.toUpperCase();
  }
  if (mode === "lower") {
    return value.toLowerCase();
  }
  return value
    .toLowerCase()
    .replace(/(^|\s)([a-z])/g, (_match, prefix: string, letter: string) => prefix + letter.toUpperCase());
}

function countCharacters(value: string): number {
  return value.length;
}

function countWords(value: string): number {
  const trimmed = value.trim();
  if (trimmed.length === 0) {
    return 0;
  }
  return trimmed.split(/\s+/).filter(Boolean).length;
}

export function transformText(raw: string, mode: string): TextTransformResult {
  const value = typeof raw === "string" ? raw : "";
  if (!isTextMode(mode)) {
    return {
      ok: false,
      error: "Choose a valid transformation: upper, lower, or title case.",
    };
  }
  const transformed = normalizeCase(value, mode);
  return {
    ok: true,
    value: transformed,
    chars: countCharacters(transformed),
    words: countWords(transformed),
  };
}

