export type DataMode = "json" | "encode" | "decode";

export interface DataToolResult {
  ok: boolean;
  value?: string;
  error?: string;
}

export function formatJson(raw: string): DataToolResult {
  const input = typeof raw === "string" ? raw.trim() : "";
  if (!input) {
    return { ok: false, error: "Paste a JSON document to format." };
  }
  try {
    const parsed = JSON.parse(input) as unknown;
    return { ok: true, value: JSON.stringify(parsed, null, 2) };
  } catch {
    return {
      ok: false,
      error: "Malformed JSON — check for missing braces, quotes, or trailing commas.",
    };
  }
}

function splitPairs(raw: string): string[] {
  const value = raw.startsWith("?") ? raw.slice(1) : raw;
  return value.split("&").filter((pair) => pair.length > 0);
}

function hasMode(mode: string): mode is DataMode {
  return mode === "json" || mode === "encode" || mode === "decode";
}

export function encodeQuery(raw: string): DataToolResult {
  const input = typeof raw === "string" ? raw.trim() : "";
  if (!input) {
    return { ok: false, error: "Enter text to encode as a URL query." };
  }
  const pairs = splitPairs(input);
  if (pairs.length === 0) {
    return { ok: false, error: "No key=value pairs found." };
  }
  const encoded = pairs.map((pair) => {
    const eq = pair.indexOf("=");
    if (eq === -1) {
      return encodeURIComponent(pair);
    }
    return `${encodeURIComponent(pair.slice(0, eq))}=${encodeURIComponent(pair.slice(eq + 1))}`;
  });
  return { ok: true, value: encoded.join("&") };
}

export function decodeQuery(raw: string): DataToolResult {
  const input = typeof raw === "string" ? raw.trim() : "";
  if (!input) {
    return { ok: false, error: "Paste an encoded URL query to decode." };
  }
  const pairs = splitPairs(input);
  if (pairs.length === 0) {
    return { ok: false, error: "No key=value pairs found." };
  }
  try {
    const decoded = pairs.map((pair) => {
      const eq = pair.indexOf("=");
      if (eq === -1) {
        return decodeURIComponent(pair);
      }
      const key = decodeURIComponent(pair.slice(0, eq));
      const value = decodeURIComponent(pair.slice(eq + 1));
      return `${key}=${value}`;
    });
    return { ok: true, value: decoded.join("\n") };
  } catch {
    return { ok: false, error: "Invalid percent-encoding — check the encoded text." };
  }
}

