export interface SeoAnalysisResult {
  ok: boolean;
  title?: string;
  description?: string;
  headings?: { h1: number; h2: number; h3: number; total: number };
  links?: { total: number; external: number; internal: number };
  images?: { total: number; withAlt: number; withoutAlt: number; coverage: number };
  error?: string;
  summary?: string;
}

interface HeadingTagMatch {
  tag: "h1" | "h2" | "h3";
  text: string;
}

function extractTagContent(html: string, tag: string): string[] {
  const results: string[] = [];
  const re = new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, "gi");
  let match: RegExpExecArray | null = re.exec(html);
  while (match !== null) {
    const content = match[1]
      .replace(/<[^>]+>/g, "")
      .replace(/&amp;/g, "&")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .trim();
    results.push(content);
    match = re.exec(html);
  }
  return results;
}

function isExternalUrl(href: string): boolean {
  const trimmed = href.trim().toLowerCase();
  if (trimmed.startsWith("http://") || trimmed.startsWith("https://")) {
    return true;
  }
  if (trimmed.startsWith("mailto:") || trimmed.startsWith("tel:")) {
    return false;
  }
  return false;
}

export function analyzeSeo(raw: string): SeoAnalysisResult {
  if (typeof raw !== "string" || raw.trim().length === 0) {
    return { ok: false, error: "Paste an HTML document to analyze." };
  }

  const html = raw;

  // Extract title
  const titleMatch = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  const title = titleMatch ? titleMatch[1].trim() : "";

  // Extract meta description
  const descMatch = html.match(
    /<meta[^>]+name\s*=\s*["']description["'][^>]+content\s*=\s*["']([^"']*)["']/i
  ) || html.match(
    /<meta[^>]+content\s*=\s*["']([^"']*)["'][^>]+name\s*=\s*["']description["']/i
  );
  const description = descMatch ? descMatch[1].trim() : "";

  // Extract headings h1-h3
  const headingCounts = { h1: 0, h2: 0, h3: 0, total: 0 };
  const headingItems: HeadingTagMatch[] = [];
  (["h1", "h2", "h3"] as const).forEach((tag) => {
    const items = extractTagContent(html, tag);
    headingCounts[tag] = items.length;
    items.forEach((text) => {
      headingItems.push({ tag, text });
    });
  });
  headingCounts.total = headingCounts.h1 + headingCounts.h2 + headingCounts.h3;

  // Extract links
  const links: string[] = [];
  const linkRe = /<a[^>]+href\s*=\s*["']([^"']*)["']/gi;
  let linkMatch: RegExpExecArray | null = linkRe.exec(html);
  while (linkMatch !== null) {
    links.push(linkMatch[1].trim());
    linkMatch = linkRe.exec(html);
  }
  const externalLinks = links.filter((href) => isExternalUrl(href));
  const linkSummary = {
    total: links.length,
    external: externalLinks.length,
    internal: links.length - externalLinks.length,
  };

  // Extract images and alt coverage
  const images: Array<{ src: string; alt: string | null; hasAlt: boolean }> = [];
  const imgRe = /<img[^>]*>/gi;
  let imgMatch: RegExpExecArray | null = imgRe.exec(html);
  while (imgMatch !== null) {
    const tag = imgMatch[0];
    const srcMatch = tag.match(/src\s*=\s*["']([^"']*)["']/i);
    const altMatch = tag.match(/alt\s*=\s*["']([^"']*)["']/i);
    const src = srcMatch ? srcMatch[1].trim() : "";
    const hasAlt = altMatch !== null;
    const alt = altMatch ? altMatch[1].trim() : null;
    images.push({ src, alt, hasAlt });
    imgMatch = imgRe.exec(html);
  }
  const withAlt = images.filter((img) => img.hasAlt && (img.alt !== null && img.alt.length > 0));
  const imageSummary = {
    total: images.length,
    withAlt: withAlt.length,
    withoutAlt: images.length - withAlt.length,
    coverage: images.length === 0 ? 100 : Math.round((withAlt.length / images.length) * 100),
  };

  // Build summary
  const parts: string[] = [];
  parts.push(
    title
      ? `Title: ${title}`
      : "Title: missing"
  );
  parts.push(
    description
      ? `Description: ${description}`
      : "Description: missing"
  );
  parts.push(
    `Headings: ${headingCounts.total} (${headingCounts.h1} h1, ${headingCounts.h2} h2, ${headingCounts.h3} h3)`
  );
  parts.push(
    `Links: ${linkSummary.total} (${linkSummary.external} external, ${linkSummary.internal} internal)`
  );
  parts.push(
    imageSummary.total > 0
      ? `Images: ${imageSummary.total} (${imageSummary.withAlt} with alt, ${imageSummary.withoutAlt} without — ${imageSummary.coverage}% coverage)`
      : "Images: none found"
  );

  const summary = parts.join("\n");

  return {
    ok: true,
    title,
    description,
    headings: headingCounts,
    links: linkSummary,
    images: imageSummary,
    summary,
  };
}

