  bmp: "image/bmp",
};

const IMAGE_MAGICS: Array<{ bytes: number[]; type: string }> = [
  { bytes: [0x89, 0x50, 0x4e, 0x47], type: "image/png" },
  { bytes: [0xff, 0xd8, 0xff], type: "image/jpeg" },
  { bytes: [0x47, 0x49, 0x46, 0x38], type: "image/gif" },
  { bytes: [0x42, 0x4d], type: "image/bmp" },
];

function dataUrlBytes(raw: string): { mime: string; base64: string } | null {
  const match = /^data:([^;,]+)?(;base64)?,(.*)$/i.exec(raw.trim());
  if (!match) {
    return null;
  }
  const mime = (match[1] || "application/octet-stream").toLowerCase();
  const base64 = match[3] ?? "";
  return { mime, base64 };
}

function decodeBase64(base64: string): Uint8Array | null {
  const clean = base64.replace(/\s/g, "");
  if (!/^[A-Za-z0-9+/]*={0,2}$/.test(clean)) {
    return null;
  }
  const binary = atob(clean);
  if (binary.length === 0) {
    return new Uint8Array(0);
  }
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

function detectImageMagic(bytes: Uint8Array): string | null {
  for (const candidate of IMAGE_MAGICS) {
    if (bytes.length < candidate.bytes.length) {
      continue;
    }
    const matches = candidate.bytes.every((value, index) => bytes[index] === value);
    if (matches) {
      return candidate.type;
    }
  }
  return null;
}

function readPngDimensions(bytes: Uint8Array): { width: number; height: number } | null {
  if (bytes.length < 24) {
    return null;
  }
  const png = detectImageMagic(bytes);
  if (png !== "image/png") {
    return null;
  }
  const width =
    (bytes[16] << 24) |
    (bytes[17] << 16) |
    (bytes[18] << 8) |
    bytes[19];
  const height =
    (bytes[20] << 24) |
    (bytes[21] << 16) |
    (bytes[22] << 8) |
    bytes[23];
  if (width <= 0 || height <= 0) {
    return null;
  }
  return { width, height };
}

function readGifDimensions(bytes: Uint8Array): { width: number; height: number } | null {
  if (bytes.length < 10) {
    return null;
  }
  if (detectImageMagic(bytes) !== "image/gif") {
    return null;
  }
  const width = bytes[6] | (bytes[7] << 8);
  const height = bytes[8] | (bytes[9] << 8);
  if (width <= 0 || height <= 0) {
    return null;
  }
  return { width, height };
}

function readBmpDimensions(bytes: Uint8Array): { width: number; height: number } | null {
  if (bytes.length < 26) {
    return null;
  }
  if (detectImageMagic(bytes) !== "image/bmp") {
    return null;
  }
  const width = Math.abs(
    (bytes[18] << 24) | (bytes[19] << 16) | (bytes[20] << 8) | bytes[21]
  );
  const height = Math.abs(
    (bytes[22] << 24) | (bytes[23] << 16) | (bytes[24] << 8) | bytes[25]
  );
  if (width <= 0 || height <= 0) {
    return null;
  }
  return { width, height };
}

function jpegSofBytes(bytes: Uint8Array): Uint8Array | null {
  let i = 2;
  while (i + 3 < bytes.length) {
    if (bytes[i] !== 0xff) {
      return null;
    }
    const marker = bytes[i + 1];
    if (
      marker >= 0xc0 &&
      marker <= 0xc3 ||
      marker >= 0xc5 &&
      marker <= 0xc7 ||
      marker >= 0xc9 &&
      marker <= 0xcb ||
      marker === 0xcd ||
      marker === 0xce
    ) {
      if (i + 9 < bytes.length) {
        const height = (bytes[i + 5] << 8) | bytes[i + 6];
        const width = (bytes[i + 7] << 8) | bytes[i + 8];
        if (width > 0 && height > 0) {
          return bytes;
        }
      }
      return null;
    }
    if (marker === 0xd8 || (marker >= 0xd0 && marker <= 0xd7) || marker === 0x01) {
      i += 2;
      continue;
    }
    if (i + 4 >= bytes.length) {
      return null;
    }
    const segmentLength = (bytes[i + 2] << 8) | bytes[i + 3];
    if (segmentLength < 2) {
      return null;
    }
    i += 2 + segmentLength;
  }
  return null;
}

function readJpegDimensions(bytes: Uint8Array): { width: number; height: number } | null {
  const markerFound = jpegSofBytes(bytes);
  if (!markerFound) {
    return null;
  }
  let i = 2;
  while (i + 3 < bytes.length) {
    if (bytes[i] !== 0xff) {
      return null;
    }
    const marker = bytes[i + 1];
    if (
      marker >= 0xc0 &&
      marker <= 0xc3 ||
      marker >= 0xc5 &&
      marker <= 0xc7 ||
      marker >= 0xc9 &&
      marker <= 0xcb ||
      marker === 0xcd ||
      marker === 0xce
    ) {
      if (i + 9 < bytes.length) {
        const height = (bytes[i + 5] << 8) | bytes[i + 6];
        const width = (bytes[i + 7] << 8) | bytes[i + 8];
        if (width > 0 && height > 0) {
          return { width, height };
        }
      }
      return null;
    }
    if (marker === 0xd8 || (marker >= 0xd0 && marker <= 0xd7) || marker === 0x01) {
      i += 2;
      continue;
    }
    if (i + 4 >= bytes.length) {
      return null;
    }
    const segmentLength = (bytes[i + 2] << 8) | bytes[i + 3];
    if (segmentLength < 2) {
      return null;
    }
    i += 2 + segmentLength;
  }
  return null;
}

function readSvgDimensions(text: string): { width: number; height: number } | null {
  const viewBox = /viewBox\s*=\s*["']\s*([-\d.]+)[\s,]+([-\d.]+)[\s,]+([-\d.]+)[\s,]+([-\d.]+)/i.exec(text);
  if (viewBox) {
    const width = Number.parseFloat(viewBox[3]);
    const height = Number.parseFloat(viewBox[4]);
    if (Number.isFinite(width) && Number.isFinite(height) && width > 0 && height > 0) {
      return { width, height };
    }
  }
  const widthAttr = /width\s*=\s*["']\s*([-\d.]+)\s*(px)?["']/i.exec(text);
  const heightAttr = /height\s*=\s*["']\s*([-\d.]+)\s*(px)?["']/i.exec(text);
  if (widthAttr && heightAttr) {
    const width = Number.parseFloat(widthAttr[1]);
    const height = Number.parseFloat(heightAttr[1]);
    if (Number.isFinite(width) && Number.isFinite(height) && width > 0 && height > 0) {
      return { width, height };
    }
  }
  return null;
}

function summarize(type: string, bytes: number, width?: number, height?: number): string {
  const sizeKb = (bytes / 1024).toFixed(1);
  const dims =
    typeof width === "number" && typeof height === "number"
      ? `${width}×${height}`
      : "unknown dimensions";
  return `${type} — ${sizeKb} KB — ${dims}`;
}

export function inspectMedia(raw: string): MediaInspectionResult {
  const value = typeof raw === "string" ? raw.trim() : "";
  if (value.length === 0) {
    return {
      ok: false,
      error: "Paste a data URL (data:image/...) or SVG markup to inspect locally.",
    };
  }

  if (value.startsWith("data:")) {
    const parsed = dataUrlBytes(value);
    if (!parsed) {
      return {
        ok: false,
        error: "Malformed data URL — expected the data:mime;base64,payload format.",
      };
    }
    const declaredMime = parsed.mime;
    const base64 = parsed.base64;
    if (base64.length === 0) {
      return {
        ok: false,
        error: "Data URL has an empty payload.",
      };
    }
    const bytes = decodeBase64(base64);
    if (!bytes) {
      return {
        ok: false,
        error: "Data URL payload is not valid base64.",
      };
    }
    const detected = detectImageMagic(bytes);
    const type = detected ?? declaredMime;
    let width: number | undefined;
    let height: number | undefined;
    if (type === "image/svg+xml" || declaredMime === "image/svg+xml") {
      let text = "";
      try {
        const decoder = new TextDecoder("utf-8");
        text = decoder.decode(bytes);
      } catch {
        text = base64.length > 0 ? atob(base64) : "";
      }
      const svgDims = readSvgDimensions(text);
      if (svgDims) {
        width = svgDims.width;
        height = svgDims.height;
      }
    } else {
      const dims =
        readPngDimensions(bytes) ??
        readGifDimensions(bytes) ??
        readJpegDimensions(bytes) ??
        readBmpDimensions(bytes);
      if (dims) {
        width = dims.width;
        height = dims.height;
      }
    }
    return {
      ok: true,
      type,
      width,
      height,
      bytes: bytes.length,
      summary: summarize(type, bytes.length, width, height),
    };
  }

  const looksSvg =
    /<svg[\s>]/i.test(value) || /xmlns\s*=\s*["']http:\/\/www\.w3\.org\/2000\/svg["']/i.test(value);
  if (looksSvg) {
    const dimensions = readSvgDimensions(value);
    return {
      ok: true,
      type: "image/svg+xml",
      width: dimensions?.width,
      height: dimensions?.height,
      bytes: value.length,
      summary: summarize("image/svg+xml", value.length, dimensions?.width, dimensions?.height),
    };
  }

  const extension = /(?:\.([a-z0-9]+))(\?|#|$)/i.exec(value);
  const mimeByExt = extension ? MIME_BY_EXTENSION[extension[1].toLowerCase()] : undefined;
  if (mimeByExt) {
    return {
      ok: true,
      type: mimeByExt,
      bytes: value.length,
      summary: summarize(mimeByExt, value.length),
    };
  }

  return {
    ok: false,
    error:
      "Only data URLs (data:image/...) or pasted SVG markup can be inspected locally. " +
      "No network or file-system access is used.",
  };
}

