export interface SocialInput {
  title: string;
  description: string;
  url: string;
}

export interface SocialPreviewResult {
  ok: boolean;
  title?: string;
  description?: string;
  url?: string;
  titleLength?: number;
  descriptionLength?: number;
  missing?: string[];
  error?: string;
  summary?: string;
}

function cleanString(value: unknown): string {
  if (typeof value !== "string") return "";
  return value.trim();
}

function truncate(value: string, max: number): string {
  if (value.length <= max) return value;
  return value.slice(0, Math.max(0, max - 1)).trimEnd() + "…";
}

function isValidUrl(value: string): boolean {
  if (value.length === 0) return false;
  if (value.length > 2048) return false;
  if (value.includes(" ")) return false;
  if (!/^https?:\/\//i.test(value)) return false;
  return true;
}

function parseFallbackJson(raw: string): SocialInput | null {
  const trimmed = raw.trim();
  if (trimmed.length === 0 || trimmed[0] !== "{") {
    return null;
  }
  try {
    const parsed = JSON.parse(trimmed) as unknown;
    if (typeof parsed !== "object" || parsed === null) {
      return null;
    }
    const record = parsed as Record<string, unknown>;
    const title = cleanString(record.title);
    const description = cleanString(record.description);
    const url = cleanString(record.url);
    if (!title && !description && !url) {
      return null;
    }
    return { title, description, url };
  } catch {
    return null;
  }
}

export function socialPreview(
  raw: string,
  fields?: SocialInput
): SocialPreviewResult {
  const trimmed = typeof raw === "string" ? raw.trim() : "";

  let input: SocialInput | null = null;

  if (fields) {
    const title = cleanString(fields.title);
    const description = cleanString(fields.description);
    const url = cleanString(fields.url);
    if (title || description || url) {
      input = { title, description, url };
    }
  }

  if (!input && trimmed.length > 0) {
    input = parseFallbackJson(trimmed);
  }

  if (!input) {
    return {
      ok: false,
      error: "Provide a title, description, and URL — either as form fields or as a JSON object like {\"title\":\"…\",\"description\":\"…\",\"url\":\"https://…\"}.",
    };
  }

  const title = input.title;
  const description = input.description;
  const url = input.url;

  const missing: string[] = [];
  if (!title) missing.push("title");
  if (!description) missing.push("description");
  if (!url) missing.push("url");

  if (!isValidUrl(url)) {
    return {
      ok: false,
      error: "URL must start with http:// or https:// and be under 2048 characters.",
    };
  }

  const displayTitle = truncate(title, 60) || "(no title)";
  const displayDescription = truncate(description, 160) || "(no description)";
  const titleLength = title.length;
  const descriptionLength = description.length;

  const notes: string[] = [];
  if (titleLength > 60) {
    notes.push(`Title is ${titleLength} chars — will be truncated at ~60 in most feeds.`);
  }
  if (descriptionLength > 160) {
    notes.push(`Description is ${descriptionLength} chars — will be truncated at ~160 in most feeds.`);
  }
  if (missing.length > 0) {
    notes.push(`Missing fields: ${missing.join(", ")}.`);
  }

  const summary = [
    `Social preview — ${displayTitle}`,
    `URL: ${url}`,
    `Description: ${displayDescription}`,
    `Title: ${titleLength} chars`,
    `Description: ${descriptionLength} chars`,
    ...(notes.length > 0 ? notes : ["Preview looks complete."]),
  ].join("\n");

  return {
    ok: true,
    title,
    description,
    url,
    titleLength,
    descriptionLength,
    missing,
    summary,
  };
}

