import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { render } from "./render";
import { dashboard } from "./ui/dashboard";
import { jsonWorkspace, categoryWorkspace } from "./ui/workspaces";
import { library, space } from "./ui/panels";

describe("Web Tools Workbench render", () => {
  const html = render();

  it("renders the dashboard with required roles", () => {
    assert.match(html, /data-role="tool-workbench"/);
    assert.match(html, /data-role="tool-brand"/);
    assert.match(html, /data-role="tool-dashboard"/);
    assert.match(html, /type="button"\s+data-role="tool-library-button"/);
    assert.match(html, /type="button"\s+data-role="tool-space-button"/);
    assert.match(html, /type="button"\s+data-role="tool-card-json"/);
  });

  it("renders all five category tiles", () => {
    assert.match(html, /data-role="tool-card-text"/);
    assert.match(html, /data-role="tool-card-data"/);
    assert.match(html, /data-role="tool-card-seo"/);
    assert.match(html, /data-role="tool-card-images"/);
    assert.match(html, /data-role="tool-card-social"/);
  });

  it("renders the JSON Formatter workspace with required roles", () => {
    assert.match(html, /data-role="tool-workspace"/);
    assert.match(html, /type="button"\s+data-role="tool-back-dashboard"/);
    assert.match(html, /data-role="tool-json-input"/);
    assert.match(html, /type="button"\s+data-role="tool-format-json"/);
    assert.match(html, /data-role="tool-json-result"/);
  });

  it("renders the library overlay closed by default", () => {
    assert.match(html, /data-role="tool-library"/);
    assert.match(html, /data-role="tool-library"\s+data-state="closed"/);
    assert.match(html, /data-role="tool-search"/);
    assert.match(html, /type="button"\s+data-role="tool-open-json"/);
    assert.match(html, /type="button"\s+data-role="tool-library-close"/);
  });

  it("renders the personal-space sheet closed by default", () => {
    assert.match(html, /data-role="tool-space-dialog"/);
    assert.match(html, /data-role="tool-space-dialog"\s+data-state="closed"/);
    assert.match(html, /type="button"\s+data-role="tool-space-close"/);
  });

  it("renders a category workspace for each tool", () => {
    const cats = ["text", "data", "seo", "images", "social"];
    for (const key of cats) {
      assert.match(html, new RegExp(`data-role="tool-category-workspace"[^>]*data-tool-category="${key}"`));
    }
  });

  it("renders category workspace inner roles", () => {
    assert.match(html, /data-role="tool-category-input"/);
    assert.match(html, /type="button"\s+data-role="tool-category-action"/);
    assert.match(html, /data-role="tool-category-result"/);
    assert.match(html, /data-role="tool-category-result"\s+data-state="idle"/);
    assert.match(html, /type="button"\s+data-role="tool-category-back"/);
  });

  it("exposes social name inputs in the social workspace", () => {
    assert.match(html, /name="title"/);
    assert.match(html, /name="description"/);
    assert.match(html, /name="url"/);
  });

  it("exposes the text workspace select with all case options", () => {
    assert.match(html, /<select[^>]*data-role="tool-category-select"/);
    assert.match(html, /<option[^>]*value="upper"/);
    assert.match(html, /<option[^>]*value="lower"/);
    assert.match(html, /<option[^>]*value="title"/);
  });

  it("exposes the data workspace select with all operation options", () => {
    assert.match(html, /<option[^>]*value="json"/);
    assert.match(html, /<option[^>]*value="encode"/);
    assert.match(html, /<option[^>]*value="decode"/);
  });

  it("includes the dock at the bottom of the dashboard", () => {
    assert.match(html, /class="[^"]*\bdock\b[^"]*"/);
  });

  it("dashboard module renders standalone with roles", () => {
    const dash = dashboard("shell", "dashboard", "card");
    assert.match(dash, /data-role="tool-dashboard"/);
    assert.match(dash, /data-role="tool-card-json"/);
    assert.match(dash, /data-role="tool-library-button"/);
    assert.match(dash, /data-role="tool-space-button"/);
  });

  it("jsonWorkspace module renders required roles", () => {
    const ws = jsonWorkspace();
    assert.match(ws, /data-role="tool-workspace"/);
    assert.match(ws, /data-role="tool-json-input"/);
    assert.match(ws, /data-role="tool-format-json"/);
    assert.match(ws, /data-role="tool-json-result"/);
    assert.match(ws, /data-role="tool-back-dashboard"/);
  });

  it("categoryWorkspace renders stable category keys and inner roles", () => {
    const text = categoryWorkspace("text", "Text & Content");
    assert.match(text, /data-role="tool-category-workspace"/);
    assert.match(text, /data-tool-category="text"/);
    assert.match(text, /data-role="tool-category-input"/);
    assert.match(text, /data-role="tool-category-action"/);
    assert.match(text, /data-role="tool-category-result"/);
    assert.match(text, /data-role="tool-category-back"/);

    const social = categoryWorkspace("social", "Social & Platforms");
    assert.match(social, /data-tool-category="social"/);
    assert.match(social, /name="title"/);
    assert.match(social, /name="description"/);
    assert.match(social, /name="url"/);
  });

  it("library module renders closed state and required roles", () => {
    const lib = library();
    assert.match(lib, /data-role="tool-library"/);
    assert.match(lib, /data-state="closed"/);
    assert.match(lib, /data-role="tool-search"/);
    assert.match(lib, /data-role="tool-open-json"/);
    assert.match(lib, /data-role="tool-library-close"/);
  });

  it("space module renders closed state and required roles", () => {
    const sp = space();
    assert.match(sp, /data-role="tool-space-dialog"/);
    assert.match(sp, /data-state="closed"/);
    assert.match(sp, /data-role="tool-space-close"/);
  });
});
